// Temporal Locality: High reuse of 'sum'
// Data remains hot in L1 cache across iterations
int data[1024];
long sum = 0;
for (int i = 0; i < 1024; i++) {
    sum += data[i];
}


// Spatial Locality: Cache-friendly row-major traversal (C/C++)
#define N 64
int matrix[N][N];
for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
        matrix[i][j] = i + j; // Stride 1 access
    }
}


// Poor Spatial Locality: High stride access (Column-major traversal)
// Causes frequent cache misses (cache line thrashing)
for (int j = 0; j < N; j++) {
    for (int i = 0; i < N; i++) {
        matrix[i][j] = i + j; // Stride N access
    }
}


// Cache Line Awareness: Preventing False Sharing in multi-threading
// Ensures Thread A's data and Thread B's data live on separate lines
struct alignas(64) ThreadSafeCounter {
    long thread_A_data;
    // Automatic padding inserted by alignas to fill cache line
    long thread_B_data;
};
